-- Generated by Loom
-- Generator: link
-- Hash function: sha256
-- Link guard (ADR 0030): this model fails at build time when
-- the input contains null, blank or hub-unmatched keys,
-- instead of silently dropping them. On dialects without a
-- message-bearing raise, the failure surfaces as a
-- division-by-zero error from the __link_guard gate.
{{ config(materialized='table') }}
WITH __link_guard AS (
    SELECT
        (SELECT COUNT(*) FROM {{ ref('stg_order_items') }} AS t
         WHERE t.order_id IS NULL OR UPPER(TRIM(CAST(t.order_id AS VARCHAR))) = ''
            OR t.customer_id IS NULL OR UPPER(TRIM(CAST(t.customer_id AS VARCHAR))) = '') AS __invalid_keys,
        (SELECT COUNT(*) FROM (
            SELECT DISTINCT t.order_id AS order_id, t.customer_id AS customer_id
            FROM {{ ref('stg_order_items') }} AS t
            WHERE t.order_id IS NOT NULL AND t.customer_id IS NOT NULL
        ) AS d
         LEFT JOIN {{ ref('hub_order') }} AS l
             ON LOWER(sha256(UPPER(TRIM(CAST(d.order_id AS VARCHAR))))) = l.order_hk
         LEFT JOIN {{ ref('hub_customer') }} AS r
             ON LOWER(sha256(UPPER(TRIM(CAST(d.customer_id AS VARCHAR))))) = r.customer_hk
         WHERE (l.order_hk IS NULL OR l.order_hk = '')
            OR (r.customer_hk IS NULL OR r.customer_hk = '')) AS __unmatched_keys
)
SELECT order_customer_hk, order_hk, customer_hk
FROM (
    SELECT
        CASE WHEN g.__invalid_keys + g.__unmatched_keys > 0 THEN error('Loom link guard: link input contains null, blank or unmatched keys') ELSE 1 END AS __guard,
        lnk.order_customer_hk AS order_customer_hk,
        lnk.order_hk AS order_hk,
        lnk.customer_hk AS customer_hk
    FROM __link_guard AS g
    LEFT JOIN (
        SELECT DISTINCT
            LOWER(sha256(concat(LOWER(sha256(UPPER(TRIM(CAST(t.order_id AS VARCHAR))))), LOWER(sha256(UPPER(TRIM(CAST(t.customer_id AS VARCHAR)))))))) AS order_customer_hk,
            LOWER(sha256(UPPER(TRIM(CAST(t.order_id AS VARCHAR))))) AS order_hk,
            LOWER(sha256(UPPER(TRIM(CAST(t.customer_id AS VARCHAR))))) AS customer_hk
        FROM {{ ref('stg_order_items') }} AS t
            JOIN {{ ref('hub_order') }} AS l
                ON LOWER(sha256(UPPER(TRIM(CAST(t.order_id AS VARCHAR))))) = l.order_hk
            JOIN {{ ref('hub_customer') }} AS r
                ON LOWER(sha256(UPPER(TRIM(CAST(t.customer_id AS VARCHAR))))) = r.customer_hk
        WHERE t.order_id IS NOT NULL
          AND t.customer_id IS NOT NULL
    ) AS lnk ON 1 = 1
) AS s
WHERE CASE WHEN s.__guard = 1 THEN s.order_customer_hk IS NOT NULL AND s.order_customer_hk <> '' ELSE FALSE END
